import unittest
import payments

class PaymentFlowTest(unittest.TestCase):
    def setUp(self):
        payments.processed.clear(); payments.charges.clear()
    def test_retry_is_idempotent_end_to_end(self):
        payments.handle('evt-1', 1250)
        payments.handle('evt-1', 1250)
        self.assertEqual([1250], payments.charges)

if __name__ == '__main__': unittest.main()

import unittest
from release_check import is_newer

class VersionTest(unittest.TestCase):
    def test_minor_versions_are_numeric(self):
        self.assertTrue(is_newer('1.10.0', '1.9.0'))
    def test_older_patch_is_rejected(self):
        self.assertFalse(is_newer('2.3.3', '2.3.4'))

if __name__ == '__main__': unittest.main()

import csv, io, unittest
from exporter import export

class ExportTest(unittest.TestCase):
    def test_accounting_round_trip(self):
        rows = [{'customer': 'ACME, \"North\"\nTeam', 'total': '12.50'}]
        parsed = list(csv.DictReader(io.StringIO(export(rows))))
        self.assertEqual(rows, parsed)

if __name__ == '__main__': unittest.main()

